public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long K = sc.nextLong();
        long[] X = new long[N];
        long[] Y = new long[N];
        for (int i = 0; i < N; i++) {
            X[i] = sc.nextLong();
            Y[i] = sc.nextLong();
        }
        long sx = sc.nextLong();
        long sy = sc.nextLong();

        // dp[i] = reachable at sprinkler i
        boolean[] dp = new boolean[N];
        for (int i = 0; i < N; i++) {
            if (dist(sx, sy, X[i], Y[i]) <= K) {
                dp[i] = true;
            }
        }

        for (int i = 0; i < N; i++) {
            if (dp[i]) {
                for (int j = i + 1; j < N; j++) {
                    if (dist(X[i], Y[i], X[j], Y[j]) <= K) {
                        dp[j] = true;
                    }
                }
            }
        }

        if (dp[N - 1]) {
            System.out.println("OK");
        } else {
            System.out.println("NA");
        }
    }

    static long dist(long x1, long y1, long x2, long y2) {
        return Math.abs(x1 - x2) + Math.abs(y1 - y2);
    }
}

