import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long sq(long x) {
        return x * x;
    }

    static boolean canReach(long x1, long y1, long x2, long y2, long d) {
        long dx = x1 - x2;
        long dy = y1 - y2;
        return dx * dx + dy * dy <= d * d;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long d = fs.nextLong();
        long sx = fs.nextLong();
        long sy = fs.nextLong();

        long[] x = new long[n];
        long[] y = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextLong();
            y[i] = fs.nextLong();
        }

        // dp[i] = whether Pyonkichi can be at sprinkler i when it operates
        boolean[] dp = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (canReach(sx, sy, x[i], y[i], d)) {
                dp[i] = true;
            }
            for (int j = 0; j < i && !dp[i]; j++) {
                if (dp[j] && canReach(x[j], y[j], x[i], y[i], d)) {
                    dp[i] = true;
                }
            }
        }

        boolean ok = false;
        for (boolean v : dp) {
            if (v) {
                ok = true;
                break;
            }
        }

        System.out.println(ok ? "OK" : "NA");
    }
}

