int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, D;
    cin >> N >> D;

    vector<pair<int, int>> sprinklers(N);
    for (int i = 0; i < N; i++) {
        cin >> sprinklers[i].first >> sprinklers[i].second;
    }

    int startX, startY;
    cin >> startX >> startY;

    vector<bool> visited(N, false);
    queue<int> q;

    // Check if starting point is within range of any sprinkler
    for (int i = 0; i < N; i++) {
        long long dx = startX - sprinklers[i].first;
        long long dy = startY - sprinklers[i].second;
        if (dx * dx + dy * dy <= (long long)D * D) {
            visited[i] = true;
            q.push(i);
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v = 0; v < N; v++) {
            if (!visited[v]) {
                long long dx = sprinklers[u].first - sprinklers[v].first;
                long long dy = sprinklers[u].second - sprinklers[v].second;
                if (dx * dx + dy * dy <= (long long)D * D) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }

    // Check if we can reach the last sprinkler
    if (visited[N - 1]) {
        cout << "OK\n";
    } else {
        cout << "NA\n";
    }

    return 0;
}

