        vector<double> pos(N), range(N);
        for (int i = 0; i < N; i++) {
            cin >> pos[i] >> range[i];
        }

        double lo = pos[0] - range[0];
        double hi = pos[0] + range[0];

        bool ok = true;
        for (int i = 1; i < N; i++) {
            double new_lo = max(lo - D, pos[i] - range[i]);
            double new_hi = min(hi + D, pos[i] + range[i]);
            if (new_lo > new_hi) {
                ok = false;
                break;
            }
            lo = new_lo;
            hi = new_hi;
        }

        cout << (ok ? "OK" : "NA") << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    double D, sx, sy;
    cin >> N >> D >> sx >> sy;

    vector<double> x(N), y(N);
    for (int i = 0; i < N; ++i) cin >> x[i] >> y[i];

    // dp[i] = whether Pyonkichi can be at sprinkler i when it is operating
    vector<int> dp(N, 0);

    // He can jump from the initial position to the first reachable sprinkler in order
    for (int i = 0; i < N; ++i) {
        double dx = x[i] - sx;
        double dy = y[i] - sy;
        if (dx * dx + dy * dy <= D * D + 1e-10) dp[i] = 1;

        // Or from any earlier reachable sprinkler
        for (int j = 0; j < i; ++j) {
            if (!dp[j]) continue;
            double ddx = x[i] - x[j];
            double ddy = y[i] - y[j];
            if (ddx * ddx + ddy * ddy <= D * D + 1e-10) {
                dp[i] = 1;
                break;
            }
        }
    }

    bool ok = false;
    for (int i = 0; i < N; ++i) {
        if (dp[i]) {
            ok = true;
            break;
        }
    }

    cout << (ok ? "OK" : "NA") << '\n';
    return 0;
}
